SELECT departments.location, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(employees.job_title))) AS job_title_values, MAX(employees.salary) - MIN(employees.salary) AS salary_range FROM employees RIGHT JOIN departments ON employees.dept_id = departments.id WHERE departments.dept_name IN ('Legal', 'Engineering', 'HR') GROUP BY departments.location ORDER BY departments.location DESC, 2 LIMIT 10
